/**
 * Google Trends-based activity grids for the best-time pages (generated by
 * scripts/fetch-best-time-trends.mjs into lib/best-time-trends-data.js). Server and markdown
 * code only: the data file is ~150 KB, so keep it out of client bundles.
 *
 * Each grid is 0–100 per local weekday × hour: Google Trends search interest in the platform
 * from that country, weighted by how many people are online each hour (Wikipedia traffic).
 */
import DATA from './best-time-trends-data.js';
import { COUNTRIES, baselineGrid, emptyGrid } from './best-time.js';

export const TRENDS_META = { fetchedAt: DATA.fetchedAt, hourly: DATA.hourly, daily: DATA.daily, activity: DATA.activity, countryCount: (DATA.measuredCountries || Object.keys(DATA.countries)).length };

/** Flat 168 scores → the { posts, clicks } grid shape the scorer expects (posts = weight). */
function toGrid(flat) {
  const g = emptyGrid();
  for (let d = 0; d < 7; d++) for (let h = 0; h < 24; h++) g[d][h] = { posts: flat[d * 24 + h] * 10, clicks: 0 };
  return g;
}

/**
 * The grid for a platform in one country: { grid, kind } where kind is 'platform' (Google
 * Trends for the platform in that country), 'country' (too few searches for the platform, so the
 * country's average across platforms) or 'activity' (no Trends data for the country yet: its own
 * Wikipedia traffic times the platform's hourly pattern from the measured countries).
 * null when we have neither for the country.
 */
export function trendsGrid(platformId, countryCode) {
  const c = DATA.countries[countryCode];
  if (!c) return null;
  if (c._method === 'activity') return Array.isArray(c[platformId]) ? { grid: toGrid(c[platformId]), kind: 'activity' } : null;
  if (Array.isArray(c[platformId])) return { grid: toGrid(c[platformId]), kind: 'platform' };
  if (Array.isArray(c._all)) return { grid: toGrid(c._all), kind: 'country' };
  return null;
}

/** A platform's grid worldwide: the mean of every country's local-time grid (its own, else the country average). */
export function trendsGlobalGrid(platformId) {
  const flats = Object.values(DATA.countries).filter((c) => c._method !== 'activity').map((c) => (Array.isArray(c[platformId]) ? c[platformId] : c._all)).filter(Array.isArray);
  if (!flats.length) return null;
  const mean = flats[0].map((_, i) => flats.reduce((s, f) => s + f[i], 0) / flats.length);
  const max = Math.max(...mean) || 1;
  return { grid: toGrid(mean.map((v) => Math.round((v / max) * 100))), kind: 'global' };
}

/**
 * For the markdown twins (no database): Trends when we have it, else the baseline.
 * @param {string} platformId
 * @param {string | null} [countryCode]
 */
export function staticGrid(platformId, countryCode = null) {
  const t = countryCode ? trendsGrid(platformId, countryCode) : trendsGlobalGrid(platformId);
  return t ? { grid: t.grid, source: 'trends', trendsKind: t.kind } : { grid: baselineGrid(platformId), source: 'baseline', trendsKind: null };
}

/** Country codes that have Trends data (for tests). */
export const trendsCountries = () => COUNTRIES.filter((c) => DATA.countries[c.code]).map((c) => c.code);
